import pgzrun
import random
WIDTH=600
HEIGHT=470
ship=Actor("spaceship")
ship.pos=(300,400)
blist=[]
blist.append(Actor("bee"))
blist[-1].x=10
blist[-1].y=-100
bullets=[]
speed=5
score=0
def update():
    global score
    if keyboard.a:
        ship.x-=speed
        if ship.x<=0:
            ship.x=0
    if keyboard.d:
        ship.x+=speed
        if ship.x>=WIDTH:
            ship.x=WIDTH
    for i in bullets:
        if i.y<=0:
            bullets.remove(i)
        else:
            i.y-=10
    for i in blist:
        i.y+=5
        if i.y>=HEIGHT:
            i.y=-100
            i.x=random.randint(50,WIDTH-50)
        for j in bullets:
            if i.colliderect(j):
                
                bullets.remove(j)
                blist.remove(i)
def draw():
    screen.fill("light blue")
    ship.draw()
    for i in blist:
        i.draw()
    for i in bullets:
        i.draw()
    screen.draw.text("Score:"+str(score),(30,30))
def on_key_down(key):
    if key==keys.SPACE:
        bullets.append(Actor("bullet"))
        bullets[-1].x=ship.x
        bullets[-1].y=ship.y-50
pgzrun.go()